  function authScreen(app,mode='login'){
    const isMfa=mode==='mfa';
    const appName=APPS[app]?.label||'ЧОППРО';
    return `<div class="proto-root"><div class="proto-frame auth-wrap"><div class="auth-brand"><div class="brand"><div class="brand-mark">Ч</div><div class="brand-copy"><strong>ЧОППРО</strong><span>Операционная система ЧОП</span></div></div><div class="hero"><span class="tag primary">${appName}</span><h1>Контроль охраны.<br>Документы. Доказательства.</h1><p>Единая среда для управления сменами, объектами, обходами, происшествиями и отчетностью с разграничением доступа по организациям и объектам.</p></div><div class="auth-points"><div class="auth-point"><strong>Multi-tenant</strong><p>Изоляция организаций и данных.</p></div><div class="auth-point"><strong>Операционный контроль</strong><p>Смены, check-in, обходы и инциденты.</p></div><div class="auth-point"><strong>Аудит</strong><p>История действий и публикаций.</p></div></div></div><div class="auth-panel"><div class="auth-card">${isMfa?`<span class="tag primary">Шаг 2 из 2</span><h2 style="margin-top:12px">Подтвердите вход</h2><p>Код отправлен на привязанный канал. Введите 6 цифр.</p><div class="otp">${Array.from({length:6},(_,i)=>`<input maxlength="1" value="${i<2?i+2:''}">`).join('')}</div><button class="btn primary" data-nav="${app}:${app==='platform'?'tenants':'dashboard'}">Подтвердить</button><button class="btn" data-toast="Новый код отправлен">Отправить код повторно</button>`:`<h2>Войти в ${appName}</h2><p>Используйте рабочую учетную запись.</p><div class="field"><label>Email или телефон</label><input value="admin@choppro.ru"></div><div class="field"><label>Пароль</label><input type="password" value="password"></div><button class="btn primary" data-nav="${app}:${app==='client'?'mfa':app==='platform'?'tenants':'mfa'}">Продолжить</button><div style="text-align:center;margin-top:16px;color:var(--muted);font-size:11px">Проблемы со входом? Обратитесь к администратору организации.</div>`}</div></div></div></div>`;
  }

